using System;using System.IO;using System.Linq;using System.Globalization;using System.Windows.Forms;
namespace ScoreModern {public sealed partial class Editor {
 int pendingGraphicalMenu;bool deletingGraphicalMenu;readonly int[] graphicalMenuStaffs=new int[4];Score pendingGraphicalMenuScore;
 bool ExecuteOriginalGraphicalMenu(string text){if(mode!=ScreenMode.Main)return false;var fields=text.Split(new[]{' ','\t'},2,StringSplitOptions.RemoveEmptyEntries);if(fields.Length==0)return false;string verb=fields[0].ToUpperInvariant();if(verb!="MU"&&verb!="MD"&&verb!="MM")return false;
  if(verb=="MM"){if(fields.Length>1)throw new NotSupportedException("MM arguments need original verification.");command.Clear();Message("");LayoutClassic();UpdateClassic();return true;}
  var values=LayoutNumbers(fields.Length>1?fields[1]:"");if(values.Length>1)throw new NotSupportedException("Graphical-menu extra arguments need original verification.");int number=values.Length==0?1:CenterWord(values[0]);if(number<1||number>3)number=1;
  if(verb=="MD"){int staff=graphicalMenuStaffs[number];if(staff==0&&!NativeEditCompatibility.ReproduceInvalidStates)throw new NotSupportedException("Deleting an unloaded menu removes staff1 in the original. Enable original invalid states to reproduce that effect.");pendingGraphicalMenu=number;deletingGraphicalMenu=true;Message("Graphic Menu #"+number+" is Staff "+staff.ToString().PadLeft(2)+". Delete all items attached to Staff "+staff.ToString().PadLeft(2)+" ? Y/N? ->");command.Clear();return true;}
  string path=NativeLibraryLocation.FileFor(source,"MENU"+number+".SET");var menu=PrepareOriginalLoadedScore(Score.Load(path));if(menu.Items.Count==0)throw new NotSupportedException("An empty graphical-menu file is not supported.");if(menu.Items.Any(i=>i.Staff!=1)&&!NativeEditCompatibility.ReproduceInvalidStates)throw new NotSupportedException("Graphical-menu files normally use staff1. The original shifts other staffs too, but MD removes only the selected staff. Enable original invalid states to reproduce that effect.");pendingGraphicalMenuScore=menu;pendingGraphicalMenu=number;deletingGraphicalMenu=false;Message("Enter an unused Staff Number for Graphic Menu #"+number+" ->");command.Clear();return true;
 }
 bool SubmitOriginalGraphicalMenu(string text){if(pendingGraphicalMenu==0)return false;int number=pendingGraphicalMenu;
  if(deletingGraphicalMenu){if(text.Equals("N",StringComparison.OrdinalIgnoreCase)){ClearGraphicalMenuPrompt();Message("");return true;}if(!text.Equals("Y",StringComparison.OrdinalIgnoreCase))return true;int staff=graphicalMenuStaffs[number];var next=score.Clone();int effectiveStaff=staff==0?1:staff;next.Items.RemoveAll(i=>i.Staff==effectiveStaff);ClearGraphicalMenuPrompt();graphicalMenuStaffs[number]=0;CommitScoreAppend(next);return true;}
  var values=LayoutNumbers(text);if(values.Length!=1)throw new InvalidDataException("Enter one unused staff number from1 to32.");int target=CenterWord(values[0]);if(target<1||target>32||score.Items.Any(i=>i.Staff==target))throw new InvalidDataException("The graphical menu requires an unused staff from1 to32.");var assembled=score.Clone();foreach(var sourceItem in pendingGraphicalMenuScore.Items){var item=sourceItem.Clone();item.Set(2,(float)((double)item.P(2)+target-1));assembled.Items.Add(item);}assembled.Encode();using(var probe=new Canvas()){probe.Score=assembled;probe.Library=canvas.Library;probe.TextLayout=canvas.TextLayout;probe.LayoutScore();}CommitScoreAppend(assembled);graphicalMenuStaffs[number]=target;ClearGraphicalMenuPrompt();return true;
 }
 void ClearGraphicalMenuPrompt(){pendingGraphicalMenu=0;deletingGraphicalMenu=false;pendingGraphicalMenuScore=null;}
 bool GraphicalMenuCharacter(KeyPressEventArgs key){if(pendingGraphicalMenu==0||!deletingGraphicalMenu)return false;key.Handled=true;SubmitOriginalGraphicalMenu(key.KeyChar.ToString());return true;}
 bool GraphicalMenuKey(KeyEventArgs key){if(pendingGraphicalMenu==0)return false;if(key.KeyCode==Keys.Escape){ClearGraphicalMenuPrompt();command.Clear();Message("");key.SuppressKeyPress=true;return true;}if(key.Control||key.Alt||key.KeyCode>=Keys.F1&&key.KeyCode<=Keys.F24){key.SuppressKeyPress=true;return true;}return false;}
}}
